import { vertical_scroll_animations } from '@/utils/animlations/vertical_scroll_animation';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import React, { Fragment, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { build_extend_animation, findScrollingElement, randomizeArray } from 'z-flux-utils';

gsap.registerPlugin(ScrollTrigger)

export default function VerticalScroll(props) {
    const {
        scrollingElement,
        direction="normal", //normal, reverse, backward
        children = <div>Nothing to Display, Please add some properly styled content</div>,
        style,
        className,
        startAnimation="bottom",  //top, within, bottom
        gsapScrollTrigger,
        scrollSpeed=1, // -.5, 0.6, 1,2,3,4,5,6 ++
        
        timeline,
        contentOrder,
        // animation="FadeUp",
        // animation="ZoomBlur",
        animation,
        extendAnimation,
    } = props

    const containerRef = useRef()
    const [height, setHeight] = useState(0)
    const useAnimation = vertical_scroll_animations[animation]

    function performCalculations(){
        function getTotalWidth(){
            const el = containerRef.current
            if(!el) return

            const children = el.children
            const first = children[0].getBoundingClientRect().width
            let total = 0

            for(let i=0; i<children.length; i++){
                const eachChild = children[i]
                const width = eachChild.getBoundingClientRect().width
                total=total+width
            }

            return total - first
        }

        const totalWidth = getTotalWidth()
        if(totalWidth) setHeight(totalWidth)
    }

    useEffect(()=>{
        performCalculations()
    }, [])

    useLayoutEffect(()=>{
        const el = containerRef.current
        if(!el || !height) return;

        const elements = [...el.children]
        const children = (
            contentOrder==="reverse"?
            elements.reverse():
            contentOrder==="random"?
            randomizeArray(elements):
            elements
        )


        
        let ctx = gsap.context(()=>{
            const scroller = scrollingElement?document.querySelector(`${scrollingElement}`):findScrollingElement(el, true);
            
            const useDirection = {
                normal: -height,
                reverse: height,
                backward: height
            }[direction]??-height

            const mid = (window.innerHeight - el.getBoundingClientRect().height)/2
            
            const start = {
                top: "top top",
                within: `top ${mid}px`,
                bottom: "bottom bottom",
            }[startAnimation]??startAnimation

            const tl = timeline||gsap.timeline({
                scrollTrigger: {
                    trigger: el,
                    scroller,
                    start,
                    end: `+=${height / scrollSpeed}`,
                    pin: true,
                    scrub: true,
                    invalidateOnRefresh: true,
                    ...gsapScrollTrigger
                }
            });

            tl.to(el, {
                x: useDirection,
                ease: "none"
            });

            // const 
            children.forEach((child) => {
                gsap.set(child, {
                    // y: "200%",
                    // x: "150",
                    // opacity: 0,
                    ...build_extend_animation(useAnimation, "from"),
                    ...build_extend_animation(extendAnimation, "from"),
                })
                gsap.to(child, {
                    // y: "0%",
                    // x: "0",
                    // opacity: 1,
                    // duration: 1,
                    ease: "power3.out",
                    ...build_extend_animation(useAnimation, "to"),
                    ...build_extend_animation(extendAnimation, "to"),
                    scrollTrigger: {
                        trigger: child,
                        containerAnimation: tl,
                        start: "left 80%",
                        end: "left 20%",
                        scrub: true,
                        toggleActions: "play none none reverse"
                    }
                });
            });
        }, containerRef)

        return ()=>ctx.revert()
    }, [
        height,
        props
    ])


    return (
        <div
            ref={containerRef} 
            style={{
                width: "100%", height: "auto", position: "relative",
                display: "flex", 
                alignItems: "flex-start",
                justifyContent: `${direction=="backward"?"flex-end":"flex-start"}`,
                flexDirection: `${direction=="reverse"?"row-reverse":"row"}`,
                // willChange: "transform",
                // transformOrigin: "bottom",
                ...style
            }}
            className={`${className} scroll_container`}
        >
            {
                React.Children.map(children, (child, index)=>{
                    return (
                        <Fragment 
                            key={index}
                        >
                            {child}
                        </Fragment>
                    )
                })
            }
        </div>
    )
}

